-- PROG003/004/007 bounded source-backed release. No answer keys are embedded in this public migration.
DO $preflight$ BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('sintagma:programs:638'));
 IF (SELECT count(*) FROM supabase_migrations.schema_migrations)<>637 OR (SELECT max(version) FROM supabase_migrations.schema_migrations)<>'20261026133000' THEN RAISE EXCEPTION 'PROG_LEDGER637_REQUIRED'; END IF;
 IF to_regclass('public.prog_content_repair_journal') IS NOT NULL THEN RAISE EXCEPTION 'PROG_ALREADY_INSTALLED'; END IF;
END $preflight$;
CREATE TEMP TABLE _prog_history_before ON COMMIT DROP AS SELECT 'test_attempts' name,count(*) n,md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' ORDER BY id),'')) digest FROM public.test_attempts t UNION ALL SELECT 'test_attempt_sessions',count(*),md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' ORDER BY id),'')) FROM public.test_attempt_sessions t UNION ALL SELECT 'test_attempt_start_requests',count(*),md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' ORDER BY to_jsonb(t)::text),'')) FROM public.test_attempt_start_requests t UNION ALL SELECT 'lesson_progress',count(*),md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' ORDER BY id),'')) FROM public.lesson_progress t;
CREATE TEMP TABLE _prog_bank_before ON COMMIT DROP AS SELECT count(*) n,md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' ORDER BY id),'')) digest FROM public.test_questions t;
CREATE TEMP TABLE _prog_materials_before ON COMMIT DROP AS SELECT count(*) n,md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' ORDER BY id),'')) digest FROM public.lessons t WHERE id<>'5be91f4b-2e89-4402-8c8e-30875a635a0a'::uuid;
CREATE TEMP TABLE _prog_listings_before ON COMMIT DROP AS SELECT id,to_jsonb(t) row_data FROM public.marketplace_courses t;
CREATE TEMP TABLE _prog_functions_before ON COMMIT DROP AS SELECT p.oid,md5(to_jsonb(p)::text) digest FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public';
-- SOURCE CANDIDATE ONLY. Not executed. No content/answer/attempt-row mutation.
-- Intended to be wrapped in the normal reviewed DRY/COMMIT release envelope.
-- NOT VALID deliberately preserves existing invalid bank rows until source-backed repair.

CREATE FUNCTION public.prog_test_question_key_valid(p_options jsonb, p_correct_answer integer)
RETURNS boolean
LANGUAGE plpgsql
IMMUTABLE
SECURITY INVOKER
SET search_path = pg_catalog
AS $key_valid$
DECLARE
  normalized_options jsonb := p_options;
BEGIN
  -- A saved draft may have no answer key. No legacy row is inferred or shifted.
  IF p_correct_answer IS NULL THEN RETURN true; END IF;
  IF p_correct_answer < 0 THEN RETURN false; END IF;
  -- Same one-level legacy JSON-string decoding as _test_normalize_options,
  -- without invoking that private helper or changing its ACL/behaviour.
  IF jsonb_typeof(normalized_options) = 'string' THEN
    BEGIN
      normalized_options := (normalized_options #>> '{}')::jsonb;
    EXCEPTION WHEN invalid_text_representation THEN
      RETURN false;
    END;
  END IF;
  IF jsonb_typeof(normalized_options) IS DISTINCT FROM 'array' THEN RETURN false; END IF;
  -- Empty arrays have length zero, so no non-NULL integer key can pass.
  RETURN p_correct_answer < jsonb_array_length(normalized_options);
END;
$key_valid$;

REVOKE ALL ON FUNCTION public.prog_test_question_key_valid(jsonb, integer) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.prog_test_question_key_valid(jsonb, integer) TO anon, authenticated, service_role;

ALTER TABLE public.test_questions
  ADD CONSTRAINT prog_test_questions_nonnull_answer_key_valid
  CHECK (CASE WHEN correct_answer IS NULL THEN true
    ELSE public.prog_test_question_key_valid(options, correct_answer) END)
  NOT VALID;

COMMENT ON CONSTRAINT prog_test_questions_nonnull_answer_key_valid ON public.test_questions IS
  'New writes require a zero-based non-NULL answer key within normalized options; NULL draft keys remain allowed. Existing rows are not scanned or repaired by this NOT VALID constraint.';

-- These operations are not covered by row-level security. Preserve normal
-- service maintenance DELETE for account erasure; no existing DML grant added.
REVOKE TRUNCATE ON TABLE public.test_attempts, public.test_attempt_sessions, public.test_attempt_start_requests
  FROM PUBLIC, anon, authenticated;

-- Content provenance only. Do not copy learner answers, attempts or personal
-- data into this journal. This is not programme/legal approval.
CREATE TABLE public.prog_content_repair_journal (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  batch_id uuid NOT NULL,
  source_table text NOT NULL CHECK (source_table IN ('test_questions', 'lessons', 'courses')),
  source_id uuid NOT NULL,
  before_row jsonb NOT NULL CHECK (jsonb_typeof(before_row) = 'object'),
  after_row jsonb NOT NULL CHECK (jsonb_typeof(after_row) = 'object'),
  before_sha256 text NOT NULL,
  after_sha256 text NOT NULL,
  source_proof jsonb NOT NULL CHECK (jsonb_typeof(source_proof) = 'object' AND source_proof <> '{}'::jsonb),
  recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  UNIQUE (batch_id, source_table, source_id),
  CHECK ((before_row->>'id') IS NOT DISTINCT FROM source_id::text AND (after_row->>'id') IS NOT DISTINCT FROM source_id::text),
  CHECK (before_sha256 = encode(sha256(convert_to(before_row::text, 'UTF8')), 'hex')),
  CHECK (after_sha256 = encode(sha256(convert_to(after_row::text, 'UTF8')), 'hex'))
);
ALTER TABLE public.prog_content_repair_journal ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.prog_content_repair_journal FROM PUBLIC, anon, authenticated, service_role;

-- Actual public default ACL also gives sandbox roles access to new tables.
-- Revoke on this NEW journal only, for every non-owner default ACL grantee.
-- This neither creates/changes roles nor changes any existing table grants.
DO $private_acl$
DECLARE
  inherited_grantee oid;
BEGIN
  FOR inherited_grantee IN
    SELECT DISTINCT a.grantee
    FROM pg_class c
    CROSS JOIN LATERAL aclexplode(coalesce(c.relacl, acldefault('r', c.relowner))) a
    WHERE c.oid = 'public.prog_content_repair_journal'::regclass AND a.grantee <> c.relowner
  LOOP
    IF inherited_grantee = 0 THEN
      REVOKE ALL ON TABLE public.prog_content_repair_journal FROM PUBLIC;
    ELSE
      EXECUTE format('REVOKE ALL ON TABLE public.prog_content_repair_journal FROM %I', pg_get_userbyid(inherited_grantee));
    END IF;
  END LOOP;
END;
$private_acl$;

CREATE FUNCTION public.prog_guard_content_repair_journal_immutable()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog
AS $journal_immutable$
BEGIN
  RAISE EXCEPTION 'Content repair history is immutable' USING ERRCODE = '42501';
END;
$journal_immutable$;
REVOKE ALL ON FUNCTION public.prog_guard_content_repair_journal_immutable() FROM PUBLIC, anon, authenticated, service_role;
CREATE TRIGGER prog_content_repair_journal_no_rewrite
  BEFORE UPDATE OR DELETE ON public.prog_content_repair_journal
  FOR EACH ROW EXECUTE FUNCTION public.prog_guard_content_repair_journal_immutable();
CREATE TRIGGER prog_content_repair_journal_no_truncate
  BEFORE TRUNCATE ON public.prog_content_repair_journal
  FOR EACH STATEMENT EXECUTE FUNCTION public.prog_guard_content_repair_journal_immutable();

COMMENT ON TABLE public.prog_content_repair_journal IS
  'Owner-only append-only source repair provenance. Before/after hashes use UTF-8 of jsonb::text, not raw file bytes. No learner results or programme/legal approval.';

