   OR source_proof->>'titleUsedAsEvidence' IS DISTINCT FROM 'false'
   OR source_proof->>'programmeApprovalGranted' IS DISTINCT FROM 'false'
   OR source_proof->>'planRowArithmeticConsistent' IS DISTINCT FROM 'true'
   OR (source_proof->>'declared_plan_total')::numeric IS DISTINCT FROM new_duration_hours::numeric)
 THEN RAISE EXCEPTION 'PROG_PASSPORT_PAYLOAD_INVALID'; END IF;
 IF to_regclass('public.prog_content_repair_journal') IS NULL THEN
   RAISE EXCEPTION 'PROG_PRIVATE_JOURNAL_REQUIRED'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_class c WHERE c.oid='public.prog_content_repair_journal'::regclass
   AND c.relrowsecurity AND pg_get_userbyid(c.relowner)=current_user)
 OR EXISTS(SELECT 1 FROM pg_policy WHERE polrelid='public.prog_content_repair_journal'::regclass)
 OR EXISTS(SELECT 1 FROM pg_class c CROSS JOIN LATERAL
   aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a
   WHERE c.oid='public.prog_content_repair_journal'::regclass AND a.grantee<>c.relowner)
 THEN RAISE EXCEPTION 'PROG_OWNER_ONLY_PRIVATE_JOURNAL_REQUIRED' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT 1 FROM public.prog_content_repair_journal WHERE batch_id=v_batch)
 THEN RAISE EXCEPTION 'PROG_BATCH_ALREADY_PRESENT_NO_BLIND_RETRY'; END IF;

 LOCK TABLE public.courses IN SHARE ROW EXCLUSIVE MODE NOWAIT;
 PERFORM l.id FROM public.lessons l JOIN _prog_passport50_expected p ON p.source_lesson_id=l.id
   ORDER BY l.id FOR SHARE OF l NOWAIT;
 PERFORM m.id FROM public.marketplace_courses m JOIN _prog_passport50_expected p ON p.marketplace_id=m.id
   ORDER BY m.id FOR SHARE OF m NOWAIT;
 IF (SELECT count(*) FROM _prog_passport50_expected p
   JOIN public.courses c ON c.id=p.course_id
   JOIN public.marketplace_courses m ON m.id=p.marketplace_id AND m.course_id=c.id
   JOIN public.course_categories cat ON cat.id=c.category_id
   JOIN public.lessons l ON l.id=p.source_lesson_id AND l.course_id=c.id
   WHERE c.organization_id='4ac2c05a-d8b5-4e72-ba31-f2c743091d95'::uuid
   AND m.organization_id=c.organization_id AND m.is_active AND m.is_validated AND c.is_published
   AND c.category_id=p.category_id AND cat.name='Новые · 2026.09'
   AND md5(to_jsonb(c)::text)=p.expected_course_row_md5
   AND l.type='text' AND md5(l.content)=p.source_content_md5
   AND c.frdo_program_type IS NULL AND c.frdo_duration_hours IS NULL
   AND encode(sha256(convert_to(l.content,'UTF8')),'hex')=p.source_proof->>'source_raw_utf8_sha256') <> 50
 THEN RAISE EXCEPTION 'PROG_SOURCE_OR_SCOPE_CHANGED_ABORT'; END IF;
 IF EXISTS(SELECT 1 FROM public.course_program_bindings b JOIN _prog_passport50_expected p ON p.course_id=b.course_id)
 THEN RAISE EXCEPTION 'PROG_EXISTING_PROGRAMME_BINDING_ABORT'; END IF;

 CREATE TEMP TABLE _prog_passport50_before ON COMMIT DROP AS
 SELECT c.id,to_jsonb(c) AS before_row FROM public.courses c JOIN _prog_passport50_expected p ON p.course_id=c.id;
 SELECT md5(coalesce(string_agg(md5(to_jsonb(c)::text),',' ORDER BY c.id),'')) INTO v_other_before
 FROM public.courses c WHERE NOT EXISTS(SELECT 1 FROM _prog_passport50_expected p WHERE p.course_id=c.id);
 FOREACH v_table IN ARRAY ARRAY['course_program_bindings','group_program_bindings','program_fact_versions',
   'program_fact_states','program_fact_events','group_program_enrollment_snapshots','education_document_program_sources']
 LOOP
   IF to_regclass('public.'||v_table) IS NULL THEN RAISE EXCEPTION 'PROG_PROTECTED_RELATION_MISSING'; END IF;
   EXECUTE format('SELECT md5(coalesce(string_agg(to_jsonb(t)::text, chr(10) ORDER BY to_jsonb(t)::text),'''')) FROM public.%I t',v_table) INTO v_fingerprint;
   v_protected_before:=v_protected_before||jsonb_build_object(v_table,v_fingerprint);
 END LOOP;

 UPDATE public.courses c SET frdo_program_type=p.new_program_type,frdo_duration_hours=p.new_duration_hours
 FROM _prog_passport50_expected p WHERE c.id=p.course_id AND c.frdo_program_type IS NULL AND c.frdo_duration_hours IS NULL;
 GET DIAGNOSTICS v_changed=ROW_COUNT;
 IF v_changed<>50 THEN RAISE EXCEPTION 'PROG_EXPECTED_FIFTY_COURSE_UPDATES'; END IF;
 IF EXISTS(SELECT 1 FROM public.courses c JOIN _prog_passport50_expected p ON p.course_id=c.id
   JOIN _prog_passport50_before b ON b.id=c.id
   WHERE c.frdo_program_type IS DISTINCT FROM p.new_program_type OR c.frdo_duration_hours IS DISTINCT FROM p.new_duration_hours
   OR (to_jsonb(c)-ARRAY['frdo_program_type','frdo_duration_hours','updated_at']::text[])
      IS DISTINCT FROM (b.before_row-ARRAY['frdo_program_type','frdo_duration_hours','updated_at']::text[]))
 THEN RAISE EXCEPTION 'PROG_NONSELECTED_COURSE_FIELD_CHANGED'; END IF;
 SELECT md5(coalesce(string_agg(md5(to_jsonb(c)::text),',' ORDER BY c.id),'')) INTO v_other_after
 FROM public.courses c WHERE NOT EXISTS(SELECT 1 FROM _prog_passport50_expected p WHERE p.course_id=c.id);
 IF v_other_before IS DISTINCT FROM v_other_after THEN RAISE EXCEPTION 'PROG_OTHER_COURSES_CHANGED'; END IF;
 FOREACH v_table IN ARRAY ARRAY['course_program_bindings','group_program_bindings','program_fact_versions',
   'program_fact_states','program_fact_events','group_program_enrollment_snapshots','education_document_program_sources']
 LOOP
   EXECUTE format('SELECT md5(coalesce(string_agg(to_jsonb(t)::text, chr(10) ORDER BY to_jsonb(t)::text),'''')) FROM public.%I t',v_table) INTO v_fingerprint;
   v_protected_after:=v_protected_after||jsonb_build_object(v_table,v_fingerprint);
 END LOOP;
 IF v_protected_before IS DISTINCT FROM v_protected_after THEN RAISE EXCEPTION 'PROG_FROZEN_PROGRAMME_STATE_CHANGED'; END IF;
 IF EXISTS(SELECT 1 FROM public.lessons l JOIN _prog_passport50_expected p ON p.source_lesson_id=l.id
   WHERE md5(l.content) IS DISTINCT FROM p.source_content_md5)
 THEN RAISE EXCEPTION 'PROG_MATERIAL_CHANGED_DURING_UPDATE'; END IF;

 INSERT INTO public.prog_content_repair_journal(batch_id,source_table,source_id,before_row,after_row,before_sha256,after_sha256,source_proof)
 SELECT v_batch,'courses',c.id,b.before_row,to_jsonb(c),
   encode(sha256(convert_to(b.before_row::text,'UTF8')),'hex'),
   encode(sha256(convert_to(to_jsonb(c)::text,'UTF8')),'hex'),p.source_proof
 FROM public.courses c JOIN _prog_passport50_before b ON b.id=c.id JOIN _prog_passport50_expected p ON p.course_id=c.id;
 GET DIAGNOSTICS v_journal=ROW_COUNT;
 IF v_journal<>50 OR (SELECT count(*) FROM public.prog_content_repair_journal WHERE batch_id=v_batch AND source_table='courses')<>50
 THEN RAISE EXCEPTION 'PROG_EXPECTED_FIFTY_PRIVATE_JOURNAL_ROWS'; END IF;
END;
$passport50_guarded$;

DO $fire_material$
DECLARE before_lesson public.lessons; after_lesson public.lessons;
BEGIN
 SELECT * INTO STRICT before_lesson FROM public.lessons WHERE id='5be91f4b-2e89-4402-8c8e-30875a635a0a'::uuid FOR UPDATE;
 IF before_lesson.course_id<>'535aba86-6863-4de6-823c-b8bad53fb3e0'::uuid OR encode(sha256(convert_to(before_lesson.content,'UTF8')),'hex')<>'9d9d095fcdda10f7e353be9352db651d81758af921cdb8f0bd9a0540d9bef507' THEN RAISE EXCEPTION 'PROG: fire source changed'; END IF;
 UPDATE public.lessons SET content=replace(content,'- **Конституция Российской Федерации.** Статья 34 провозглашает право каждого на благоприятную окружающую среду, а статья 42 — право на возмещение ущерба, причиненного здоровью или имуществу экологическим правонарушением. Эти положения косвенно относятся и к пожарной безопасности, как к фактору, влияющему на состояние окружающей среды и безопасность жизнедеятельности.','- **Конституция Российской Федерации.** Статья 42 закрепляет право каждого на благоприятную окружающую среду, достоверную информацию о её состоянии и возмещение ущерба, причинённого здоровью или имуществу экологическим правонарушением. Эти положения косвенно относятся и к пожарной безопасности как фактору, влияющему на состояние окружающей среды и безопасность жизнедеятельности.') WHERE id=before_lesson.id RETURNING * INTO STRICT after_lesson;
 IF encode(sha256(convert_to(after_lesson.content,'UTF8')),'hex')<>'b38b01078153ad1af882d38d609e12c42f01de6b67fc2b1700e7df7b788f0b66' THEN RAISE EXCEPTION 'PROG: fire after mismatch'; END IF;
 INSERT INTO public.prog_content_repair_journal(batch_id,source_table,source_id,before_row,after_row,before_sha256,after_sha256,source_proof) VALUES('693657fa-42a0-42be-849b-007026101600'::uuid,'lessons',before_lesson.id,to_jsonb(before_lesson),to_jsonb(after_lesson),encode(sha256(convert_to(to_jsonb(before_lesson)::text,'UTF8')),'hex'),encode(sha256(convert_to(to_jsonb(after_lesson)::text,'UTF8')),'hex'),'{"kind":"verified_material_correction","source":"https://www.minjust.gov.ru/ru/documents/8011/","section":"Конституция РФ, статья42","checkedAt":"2026-10-26T04:58:38.312Z","reason":"Article42 protects all three named environmental rights; article34 is economic activity. Exact paragraph repair, no broader legal approval.","legalApproval":false}'::jsonb);
END;
$fire_material$;


CREATE TEMP TABLE _prog_revalidate_exact ON COMMIT DROP AS SELECT marketplace_id id,course_id FROM _prog_passport50_expected UNION ALL SELECT 'd37e2e11-12ef-4cf0-88d2-f8f7b59b1584'::uuid,'535aba86-6863-4de6-823c-b8bad53fb3e0'::uuid;
DO $source_revalidation$
DECLARE n integer;
BEGIN
 IF (SELECT count(*) FROM _prog_revalidate_exact)<>51 THEN RAISE EXCEPTION 'PROG_EXACT51_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM _prog_revalidate_exact x JOIN public.courses c ON c.id=x.course_id WHERE c.organization_id<>'4ac2c05a-d8b5-4e72-ba31-f2c743091d95'::uuid OR NOT c.is_published) THEN RAISE EXCEPTION 'PROG_SOURCE_SCOPE_CHANGED'; END IF;
 IF EXISTS(SELECT 1 FROM public.lessons l JOIN _prog_revalidate_exact x ON x.course_id=l.course_id WHERE l.type='test' AND NOT EXISTS(SELECT 1 FROM public.test_questions q WHERE q.lesson_id=l.id)) THEN RAISE EXCEPTION 'PROG_EMPTY_TEST_NOT_REVALIDATED'; END IF;
 IF EXISTS(SELECT 1 FROM public.test_questions q JOIN public.lessons l ON l.id=q.lesson_id JOIN _prog_revalidate_exact x ON x.course_id=l.course_id WHERE q.correct_answer IS NULL OR NOT public.prog_test_question_key_valid(q.options,q.correct_answer)) THEN RAISE EXCEPTION 'PROG_BAD_KEY_NOT_REVALIDATED'; END IF;
 IF EXISTS(SELECT 1 FROM _prog_revalidate_exact x JOIN _prog_listings_before b ON b.id=x.id WHERE NOT(b.row_data->>'is_active')::boolean OR NOT(b.row_data->>'is_validated')::boolean) THEN RAISE EXCEPTION 'PROG_PRIOR_LISTING_STATE_CHANGED'; END IF;
 UPDATE public.marketplace_courses m SET is_validated=(b.row_data->>'is_validated')::boolean FROM _prog_revalidate_exact x JOIN _prog_listings_before b ON b.id=x.id WHERE m.id=x.id AND m.course_id=x.course_id;
 GET DIAGNOSTICS n=ROW_COUNT; IF n<>51 THEN RAISE EXCEPTION 'PROG_EXACT51_REVALIDATION_FAILED'; END IF;
END $source_revalidation$;
DO $preservation_after$
BEGIN
 IF EXISTS((SELECT * FROM _prog_history_before EXCEPT (SELECT 'test_attempts' name,count(*) n,md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' ORDER BY id),'')) digest FROM public.test_attempts t UNION ALL SELECT 'test_attempt_sessions',count(*),md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' ORDER BY id),'')) FROM public.test_attempt_sessions t UNION ALL SELECT 'test_attempt_start_requests',count(*),md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' ORDER BY to_jsonb(t)::text),'')) FROM public.test_attempt_start_requests t UNION ALL SELECT 'lesson_progress',count(*),md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' ORDER BY id),'')) FROM public.lesson_progress t)) UNION ALL ((SELECT 'test_attempts' name,count(*) n,md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' ORDER BY id),'')) digest FROM public.test_attempts t UNION ALL SELECT 'test_attempt_sessions',count(*),md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' ORDER BY id),'')) FROM public.test_attempt_sessions t UNION ALL SELECT 'test_attempt_start_requests',count(*),md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' ORDER BY to_jsonb(t)::text),'')) FROM public.test_attempt_start_requests t UNION ALL SELECT 'lesson_progress',count(*),md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' ORDER BY id),'')) FROM public.lesson_progress t) EXCEPT SELECT * FROM _prog_history_before)) THEN RAISE EXCEPTION 'PROG_OLD_ATTEMPTS_RESULTS_PROGRESS_CHANGED'; END IF;
 IF (SELECT row(n,digest) FROM _prog_bank_before) IS DISTINCT FROM (SELECT row(count(*),md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' ORDER BY id),''))) FROM public.test_questions t) THEN RAISE EXCEPTION 'PROG_BANK_CHANGED_BEFORE_SUBJECT_REVIEW'; END IF;
 IF (SELECT row(n,digest) FROM _prog_materials_before) IS DISTINCT FROM (SELECT row(count(*),md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' ORDER BY id),''))) FROM public.lessons t WHERE id<>'5be91f4b-2e89-4402-8c8e-30875a635a0a'::uuid) THEN RAISE EXCEPTION 'PROG_UNRELATED_MATERIAL_CHANGED'; END IF;
 IF EXISTS(SELECT 1 FROM _prog_functions_before b LEFT JOIN pg_proc p ON p.oid=b.oid WHERE p.oid IS NULL OR md5(to_jsonb(p)::text) IS DISTINCT FROM b.digest) THEN RAISE EXCEPTION 'PROG_EXISTING_FUNCTION_OR_AUTHORITY_CHANGED'; END IF;
 IF EXISTS(SELECT 1 FROM _prog_listings_before b FULL JOIN public.marketplace_courses m ON m.id=b.id LEFT JOIN _prog_revalidate_exact x ON x.id=b.id WHERE b.id IS NULL OR m.id IS NULL OR CASE WHEN x.id IS NOT NULL THEN b.row_data-'updated_at' IS DISTINCT FROM to_jsonb(m)-'updated_at' ELSE b.row_data IS DISTINCT FROM to_jsonb(m) END) THEN RAISE EXCEPTION 'PROG_LISTING_OR_PRICE_CHANGED'; END IF;
 IF (SELECT count(*) FROM public.prog_content_repair_journal)<>51 THEN RAISE EXCEPTION 'PROG_EXPECTED51_PROVENANCE_ROWS'; END IF;
 IF EXISTS(SELECT 1 FROM pg_class c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE c.oid='public.prog_content_repair_journal'::regclass AND a.grantee<>c.relowner) OR EXISTS(SELECT 1 FROM pg_policy WHERE polrelid='public.prog_content_repair_journal'::regclass) THEN RAISE EXCEPTION 'PROG_JOURNAL_NOT_PRIVATE'; END IF;
 IF EXISTS(SELECT 1 FROM unnest(ARRAY['anon','authenticated']) roles(role_name) CROSS JOIN unnest(ARRAY['test_attempts','test_attempt_sessions','test_attempt_start_requests']) rels(table_name) WHERE has_table_privilege(roles.role_name,'public.'||rels.table_name,'TRUNCATE')) THEN RAISE EXCEPTION 'PROG_HISTORY_TRUNCATE_PERMISSION_REMAINS'; END IF;
 IF (SELECT convalidated FROM pg_constraint WHERE conname='prog_test_questions_nonnull_answer_key_valid' AND conrelid='public.test_questions'::regclass) IS DISTINCT FROM false THEN RAISE EXCEPTION 'PROG_LEGACY_CONSTRAINT_NOT_VALID_REQUIRED'; END IF;
END $preservation_after$;
